-- MI MES COMPARTIDO - ESQUEMA SUPABASE v2.0
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default 'Integrante',created_at timestamptz not null default now());
create table if not exists public.households(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 60),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.household_members(household_id uuid references public.households(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null default 'member' check(role in('admin','member')),joined_at timestamptz not null default now(),primary key(household_id,user_id));
create table if not exists public.monthly_budgets(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,month date not null,salary numeric(14,0) not null default 0 check(salary>=0),other_income numeric(14,0) not null default 0 check(other_income>=0),updated_by uuid default auth.uid() references auth.users(id),updated_at timestamptz not null default now(),unique(household_id,month));
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,concept text not null check(char_length(concept) between 1 and 80),amount numeric(14,0) not null check(amount>0),category text not null,spent_on date not null,payment_method text,note text,created_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,month date not null,name text not null check(char_length(name) between 1 and 100),amount numeric(14,0) not null check(amount>0),priority text not null default 'Media' check(priority in('Alta','Media','Baja')),target_date date,note text,reserved boolean not null default false,completed boolean not null default false,created_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.household_invites(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,code text not null unique,created_by uuid not null references auth.users(id),expires_at timestamptz not null,used_by uuid references auth.users(id),used_at timestamptz,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Integrante')) on conflict(id) do nothing;return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_household_member(p_household uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.household_members where household_id=p_household and user_id=auth.uid())$$;
create or replace function public.is_household_admin(p_household uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.household_members where household_id=p_household and user_id=auth.uid() and role='admin')$$;
create or replace function public.create_household(p_name text) returns uuid language plpgsql security definer set search_path=public as $$declare h uuid;begin if auth.uid() is null then raise exception 'Debes iniciar sesión';end if;insert into households(name,created_by) values(trim(p_name),auth.uid()) returning id into h;insert into household_members(household_id,user_id,role) values(h,auth.uid(),'admin');return h;end$$;
create or replace function public.create_household_invite(p_household_id uuid) returns text language plpgsql security definer set search_path=public as $$declare c text;begin if not is_household_admin(p_household_id) then raise exception 'Solo un administrador puede invitar';end if;c:=upper(substr(encode(gen_random_bytes(6),'hex'),1,8));insert into household_invites(household_id,code,created_by,expires_at) values(p_household_id,c,auth.uid(),now()+interval '48 hours');return c;end$$;
create or replace function public.join_household(p_code text) returns uuid language plpgsql security definer set search_path=public as $$declare i household_invites%rowtype;begin select * into i from household_invites where code=upper(trim(p_code)) and used_by is null and expires_at>now() for update;if not found then raise exception 'Código inválido, vencido o utilizado';end if;insert into household_members(household_id,user_id,role) values(i.household_id,auth.uid(),'member') on conflict do nothing;update household_invites set used_by=auth.uid(),used_at=now() where id=i.id;return i.household_id;end$$;
create or replace function public.complete_project(p_project_id uuid,p_spent_on date) returns uuid language plpgsql security definer set search_path=public as $$declare p projects%rowtype;e uuid;begin select * into p from projects where id=p_project_id and is_household_member(household_id) for update;if not found then raise exception 'Proyecto no disponible';end if;insert into expenses(household_id,concept,amount,category,spent_on,payment_method,note,created_by) values(p.household_id,p.name,p.amount,'Otros',p_spent_on,'Débito',coalesce(p.note,'Proyecto convertido en gasto'),auth.uid()) returning id into e;update projects set completed=true,reserved=false,updated_at=now() where id=p.id;return e;end$$;
alter table profiles enable row level security;alter table households enable row level security;alter table household_members enable row level security;alter table monthly_budgets enable row level security;alter table expenses enable row level security;alter table projects enable row level security;alter table household_invites enable row level security;
drop policy if exists profiles_shared on profiles;create policy profiles_shared on profiles for select to authenticated using(id=auth.uid() or exists(select 1 from household_members a join household_members b on a.household_id=b.household_id where a.user_id=auth.uid() and b.user_id=profiles.id));
drop policy if exists households_member on households;create policy households_member on households for select to authenticated using(is_household_member(id));
drop policy if exists members_member on household_members;create policy members_member on household_members for select to authenticated using(is_household_member(household_id));
drop policy if exists budgets_member_all on monthly_budgets;create policy budgets_member_all on monthly_budgets for all to authenticated using(is_household_member(household_id)) with check(is_household_member(household_id));
drop policy if exists expenses_member_all on expenses;create policy expenses_member_all on expenses for all to authenticated using(is_household_member(household_id)) with check(is_household_member(household_id));
drop policy if exists projects_member_all on projects;create policy projects_member_all on projects for all to authenticated using(is_household_member(household_id)) with check(is_household_member(household_id));
drop policy if exists invites_admin_select on household_invites;create policy invites_admin_select on household_invites for select to authenticated using(is_household_admin(household_id));
revoke execute on function create_household(text),create_household_invite(uuid),join_household(text),complete_project(uuid,date) from public,anon;
grant usage on schema public to authenticated;grant select on profiles,households,household_members to authenticated;grant select,insert,update,delete on monthly_budgets,expenses,projects to authenticated;grant execute on function create_household(text),create_household_invite(uuid),join_household(text),complete_project(uuid,date),is_household_member(uuid),is_household_admin(uuid) to authenticated;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='expenses') then alter publication supabase_realtime add table public.expenses;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='projects') then alter publication supabase_realtime add table public.projects;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='monthly_budgets') then alter publication supabase_realtime add table public.monthly_budgets;end if;end$$;
